{
  "гриб": "Amanita caesarea (цезарский гриб, мухомор Цезаря, царский гриб)",
  "состав": [
    {
      "вещество": "Вода",
      "содержание": "86–90 % от свежего веса",
      "влияние": "Составляет основную массу плодового тела и не оказывает специфического физиологического действия на организм человека."
    },
    {
      "вещество": "Белки и свободные аминокислоты (глутаминовая, аспарагиновая, глицин, аланин и др.)",
      "содержание": "2,5–4 % от свежего веса (≈ 25–35 % от сухого веса)",
      "влияние": "Являются источником незаменимых аминокислот и участвуют в построении и восстановлении тканей организма при пищеварении."
    },
    {
      "вещество": "Хитин (полисахарид клеточных стенок)",
      "содержание": "1–2 % от свежего веса",
      "влияние": "Не переваривается полностью в ЖКТ человека и действует как нерастворимый пищевое волокно, слегка стимулируя перистальтику кишечника."
    },
    {
      "вещество": "Углеводы (глюкоза, мальтоза, mannitol, β-глюканы)",
      "содержание": "5–8 % от свежего веса",
      "влияние": "Служат источником энергии; mannitol в значительных дозах может оказывать лёгкое слабящее действие."
    },
    {
      "вещество": "Липиды (эргостерол, фосфолипиды, жирные кислоты)",
      "содержание": "0,3–0,8 % от свежего веса",
      "влияние": "Эргостерол при воздействии УФ-света превращается в провитамин D₂, участвующий в метаболизме кальция."
    },
    {
      "вещество": "Калий (K⁺)",
      "содержание": "0,3–0,5 % от свежего веса (≈ 3000–5000 мг/кг сухого веса)",
      "влияние": "Поддерживает водно-электролитный баланс и нормальную работу сердца и мышц."
    },
    {
      "вещество": "Фосфор (P)",
      "содержание": "0,1–0,2 % от свежего веса (≈ 1000–2000 мг/кг сухого веса)",
      "влияние": "Входит в состав АТФ, нуклеотидов и костной ткани; необходим для энергетического обмена."
    },
    {
      "вещество": "Рибофлавин (витамин B₂)",
      "содержание": "0,3–1,0 мг/100 г свежего веса",
      "влияние": "Является кофактором окислительно-восстановительных ферментов и участвует в клеточном дыхании."
    },
    {
      "вещество": "Ниацин (витамин B₃ / PP)",
      "содержание": "1–3 мг/100 г свежего веса",
      "влияние": "Входит в состав коферментов NAD⁺/NADP⁺ и необходим для метаболизма углеводов, жиров и белков."
    },
    {
      "вещество": "Другие минералы (Mg, Ca, Fe, Zn, Se, Na)",
      "содержание": "0,2–0,4 % от свежего веса суммарно",
      "влияние": "Обеспечивают ферментативную активность, кислотно-основной баланс и антиоксидантную защиту организма."
    },
    {
      "вещество": "Летучие ароматические соединения (терпены, альдегиды, спирты)",
      "содержание": "неизвестно (следовые, < 0,01 % от свежего веса)",
      "влияние": "Обеспечивают характерный пряно-ореховый аромат и в пищевых количествах безопасны, лишь слегка усиливают аппетит."
    }
  ]
}
